require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_admin();$items=db()->query('SELECT l.*,u.name seller,u.is_active seller_active FROM listings l JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC')->fetchAll();$pageTitle='Listings';include dirname(__DIR__).'/includes/header.php';?><div class="section-head"><div><h2>Manage listings</h2><p>Moderation status and marketplace availability are tracked separately.</p></div></div><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Seller</th><th>Price</th><th>Moderation</th><th>Availability</th><th>Trust</th><th>Score</th></tr><?php foreach($items as$l):?><tr><td><a href="/listing.php?id=<?=$l['id']?>"><?=e($l['title'])?></a></td><td><a href="/profile.php?id=<?=$l['user_id']?>"><?=e($l['seller'])?></a><?=$l['seller_active']?'':' · disabled'?></td><td><?=money($l['price'])?></td><td><?=e($l['status'])?></td><td><?=e(availability_label((string)($l['availability_status']??'available')))?></td><td><?=e(trust_label((string)($l['trust_status']??''),(string)$l['status']))?></td><td><?=e((string)($l['fraud_score']??'—'))?></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/includes/footer.php';?>
